local zones = {
	[947] = {
		name = "Azeroth",
		short = "Vor zehntausend Jahren folgten die Hochgeborenen Kalimdors, berauscht von der Macht des Brunnens der Ewigkeit, dem Ruf des gefallenen Titanen Sargeras und rissen ein Tor für die Brennende Legion auf.",
		full = "Vor zehntausend Jahren folgten die Hochgeborenen Kalimdors, berauscht von der Macht des Brunnens der Ewigkeit, dem Ruf des gefallenen Titanen Sargeras und rissen ein Tor für die Brennende Legion auf. Malfurion Sturmgrimm und der Widerstand der Kaldorei zerschmetterten dieses Tor mit der Drachenseele und schleuderten Sargeras zurück in den Wirbelnden Nether, doch der Zusammenbruch des Brunnens zerbrach die Welt selbst. Das alte Kalimdor versank in Feuer und Flut; zerschlagene Kontinente erhoben sich aus den Trümmern, und das ertrunkene Herz des Landes wurde zum Großen Meer, in dem der Mahlstrom dort tobt, wo einst der Brunnen lag.",
		source = "https://warcraft.wiki.gg/wiki/Azeroth",
	},
	[1411] = {
		name = "Durotar",
		short = "Durotar ist ein zerklüftetes, rotes Land aus Felsen und Schluchten, trocken und heiß, arm an Wasser und an allem, was grünt.",
		full = "Durotar ist ein zerklüftetes, rotes Land aus Felsen und Schluchten, trocken und heiß, arm an Wasser und an allem, was grünt. Die Orcs finden darin eine raue Schönheit, die an Draenor erinnert, und hierher führte Thrall sein Volk nach der Schlacht am Berg Hyjal, um eine neue Heimat zu errichten, die er nach seinem ermordeten Vater Durotan benannte. Das Land hatte einst den Stachelebern der Grimmhauer gehört, bis die Horde sie vertrieb.\n\nDieser Frieden währte nicht lange. Großadmiral Daelin Prachtmeer, ein Held des Zweiten Krieges und kein Freund der Orcs, führte eine gewaltige Flotte der Allianz gegen Durotar, fest entschlossen, die Horde zu zerschlagen, ehe sie Wurzeln schlagen konnte. Seine Tochter Jaina entschied sich anders: Bei Theramore stellte sie sich gegen ihren eigenen Vater und kämpfte an Thralls Seite, und Daelin fiel in der Schlacht, bevor die beiden sich je versöhnen konnten. Aus Dankbarkeit für ihre Treue ließ Thrall Jainas Soldaten unversehrt nach Theramore abziehen.\n\nDie Darkspeartrolle kamen als Verbannte an Durotars Küste, nicht als Siedler aus freien Stücken. Von einem der Ihren verraten, dem Hexer Zalazane, wurden sie von ihrer Heimat auf den Echoinseln vertrieben und errichteten am Festlandufer das Fischerdorf Sen'jin, ohne je zurückerobern zu können, was Zalazane ihnen genommen hatte.",
		source = "https://warcraft.wiki.gg/wiki/Durotar_(Classic)",
	},
	[1412] = {
		name = "Mulgore",
		short = "Hunderte von Jahren besaßen die Tauren kein eigenes Land, gejagt quer durch Kalimdor von Zentaurenhorden, die ihre Stämme in umherziehende Lager zersprengten.",
		full = "Hunderte von Jahren besaßen die Tauren kein eigenes Land, gejagt quer durch Kalimdor von Zentaurenhorden, die ihre Stämme in umherziehende Lager zersprengten. Als Thrall und seine Orcs an diesen Küsten landeten, sah Cairne Bloodhoof in ihnen verwandte Seelen, ehrenhaft und stark. Mit dem Geleit der Orcs und ihrer Stärke im Rücken führte Cairne sein Volk in das geschützte Tal, das auf allen Seiten von Bergen umschlossen ist, und dort vertrieb sein Stamm der Bloodhoof die Zentauren aus dem Grasland und nahm es endlich in Besitz.\n\nAuf dem Tafelberg, der sich über die Ebene erhob, errichtete Cairne Thunder Bluff, eine Zuflucht für Tauren aller Stämme, und mit der Zeit vereinten sich die verstreuten Völker unter seiner Herrschaft.\n\nDie Weiden sind noch immer grün, die Tafelberge werfen noch immer ihre langen Schatten über Bloodhoof, und jeder Tauren, der erwachsen wird, muss noch immer in die wilden Ebenen hinausziehen, um sich bei der Großen Jagd zu beweisen, so wie es seine Ahnen taten.",
		source = "https://warcraft.wiki.gg/wiki/Mulgore_(Classic)",
	},
	[1413] = {
		name = "Das Brachland",
		short = "Der Staub hier war nicht immer Staub. Einst war dies Wald, gehegt von den Kaldorei, die den Außenposten Then'Ralore errichteten, und es heißt, der Halbgott Lo'Gosh habe sich hier im Krieg der Ahnen der Brennenden Legion entgegengestellt.",
		full = "Der Staub hier war nicht immer Staub. Einst war dies Wald, gehegt von den Kaldorei, die den Außenposten Then'Ralore errichteten, und es heißt, der Halbgott Lo'Gosh habe sich hier im Krieg der Ahnen der Brennenden Legion entgegengestellt. Die Große Teilung setzte all dem ein Ende, und das grüne Tal wurde zu der sonnenversengten Ebene, die es heute ist.\n\nÜber Generationen zogen die Tauren durch diese Ebenen, jagten Kodos und Donnerechsen, suchten die Weisheit der Erdenmutter und wurden stets von Zentauren verfolgt, die sie zum Vergnügen jagten. Sie wehrten sich, doch nie aus Liebe zum Krieg; kamen die Pferdemenschen, brachen sie ihre Zelte ab und zogen weiter, statt Leben zu verschwenden. Ein Jahr des Friedens, ein Jahr des Krieges – so war das Leben der Tauren, bis Thralls Orcs und die Darkspeartrolle landeten und mit den Tauren der Bloodhoof gegen die Zentauren zogen. Nach dem Fall der Legion am Berg Hyjal beanspruchte Thrall das östliche Brachland, vertrieb die Stacheleber der Grimmhauer, nannte das Land Durotar und errichtete Orgrimmar als seine Hauptstadt.\n\nDas Land birgt auch ältere Schmerzen: Es heißt, ein Mann namens Dethorin fand seine Geliebte Allurana in den Armen eines anderen, und sein Schrei riss die Axt Killmaim aus dem Sand empor – dieselbe Klinge, mit der er sie getötet hatte.",
		source = "https://warcraft.wiki.gg/wiki/Barrens_(Classic)",
	},
	[1414] = {
		name = "Kalimdor",
		short = "Nachdem die Teilung die Welt zerbrochen hatte, zogen sich die verbliebenen Nachtelfen bewusst vom Rest der Welt zurück.",
		full = "Nachdem die Teilung die Welt zerbrochen hatte, zogen sich die verbliebenen Nachtelfen bewusst vom Rest der Welt zurück. Unter den Menschen überlebte Kalimdor nur als Legende, ein Land, das angeblich zerbrochen und in den Wellen versunken war, ohne dass sie Lage oder Gestalt gekannt hätten.\n\nDoch es war nicht völlig vergessen. In den folgenden Jahren besuchten Nachtelfen die Quel'dorei, und so wussten allein die Hochelfen von Quel'Thalas, dass die Legende wahr war.\n\nSelbst als der Dritte Krieg kam, weigerten sich die meisten Menschen noch immer zu glauben, dass es Kalimdor gab, darunter sogar der Gesandte der Kirin Tor am Hof von König Terenas. Nur wenige folgten Medivhs Warnung und segelten nach Westen, unter ihnen Thralls neue Horde, gefolgt von Jaina Prachtmeers Expedition. Was sie fanden, war keine Legende, sondern ein ganzer Kontinent, mit Eis im Norden, Wüste im Süden und Nachtelfen, die noch immer die Wälder dazwischen hielten.",
		source = "https://warcraft.wiki.gg/wiki/Kalimdor",
	},
	[1415] = {
		name = "Östliche Königreiche",
		short = "Die Östlichen Königreiche waren nicht immer viele Länder.",
		full = "Die Östlichen Königreiche waren nicht immer viele Länder. Einst gehörten sie zu einem einzigen Kontinent, bevor die Große Teilung die Welt zerriss und die zerbrochenen Stücke zurückließ, die man heute Azeroth, Khaz Modan und Lordaeron nennt, wobei sich Quel'Thalas an den Norden jenes letzten zerschlagenen Landes klammert, bis heute ungewiss, ob es ein eigenes Land ist oder nur ein Winkel eines anderen.\n\nÜber diese Bruchstücke hinweg erheben sich die Berge von Khaz Modan und das Rotkammgebirge wie ein Rückgrat durch das Herz des Kontinents, und um sie herum überdauern die alten Völker: Zwerge und Gnome in ihren tiefen Hallen, Menschen in ihren Königreichen, Hochelfen in ihren Wäldern, und nun die Verlassenen, die sich dort erhoben haben, wo einst Lordaerons Volk lebte. Auch Orcs, Goblins, Naga und Oger haben ihren Weg in diese Lande gefunden, obwohl keiner von ihnen hier geboren wurde.\n\nDie Narben jenes ersten Bruchs sind noch immer die Wahrheit dieses Ortes. Jede Grenze hier, jede Meerenge und jeder Streifen versunkenen Landes zwischen einem Königreich und dem nächsten erinnert daran, dass die Östlichen Königreiche einst ein Ganzes waren und es nicht mehr sind.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Kingdoms",
	},
	[1416] = {
		name = "Alteracgebirge",
		short = "Auf diesen Gipfeln hört der Regen nie ganz auf, und der Himmel über ihnen ist stets grau. Einst krönten die Berge den Stadtstaat Alterac, der über weite Teile der Nordlande herrschte und zudem Dalaran Schutz bot.",
		full = "Auf diesen Gipfeln hört der Regen nie ganz auf, und der Himmel über ihnen ist stets grau. Einst krönten die Berge den Stadtstaat Alterac, der über weite Teile der Nordlande herrschte und zudem Dalaran Schutz bot. Beide sind nun vergangen, und was übrig ist, erklärt, warum sich so wenige hier hinaufwagen.\n\nAls der Zweite Krieg endete, erfuhr die Allianz von Lordaeron, dass Alteracs Fürsten insgeheim mit der Horde paktiert hatten, und schickte ein Heer in diese Berge, um die Verräter an ihrem eigenen Herd zu treffen. Die Stadt fiel, ihr Volk wurde zerstreut oder eingekerkert, und ihr Geschlecht gewann seinen Thron nie zurück. Ein späterer Prinz dieses gefallenen Hauses, Aliden Perenolde, erhob sich stattdessen als Banditenfürst und sammelte die Ausgestoßenen und Rachsüchtigen im Syndikat, einer Bande von Schurken, die noch immer Strahnbrad hält und diese Hänge durchstreift, um zurückzuerobern, was seine Familie verloren hat.\n\nHeute gehören die Ruinen von Alterac den Crushridge-Ogern, und das Syndikat hält vieles von dem, was die Oger nicht besitzen.",
		source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains_(Classic)",
	},
	[1417] = {
		name = "Arathihochland",
		short = "König Thoradin kam in dieses dürre Land, weil ein Traum ihm verhieß, dass sein Volk hier gedeihen würde, und er errichtete darauf Strom, die erste Hauptstadt eines geeinten Arathor.",
		full = "König Thoradin kam in dieses dürre Land, weil ein Traum ihm verhieß, dass sein Volk hier gedeihen würde, und er errichtete darauf Strom, die erste Hauptstadt eines geeinten Arathor. Der trockene Boden diente ihm als Dornenwall und verwehrte den Waldtrollen der Amani die Deckung für ihre Hinterhalte, und er errichtete zudem eine zweite Mauer. Tausend Jahre lang stand Strom im Herzen des Reiches, bis seine Adelshäuser zu reicheren Böden abwanderten und Thoradins letzte Nachfahren fortzogen, um Stormwind zu gründen. Was blieb, wurde zu Stromgarde, das fortan vom Geschlecht der Trollbann gehalten wurde.\n\nStromgarde ist inzwischen gefallen, überrannt von Ogern und dem Syndikat, und seine Überlebenden wurden aus der Burg in eine Schlucht vertrieben, die sie heute Die Zuflucht nennen. In der Nähe liegt Hammerfall, einst ein Lager, in dem die Menschheit ihre orcischen Gefangenen einsperrte, heute von den Orcs selbst gehalten und zu Ehren von Orgrim Schicksalshammer umbenannt.\n\nThoradins große Mauer ist zu einer klaffenden Ruine zerfallen, und seine Burg liegt zerbrochen und umkämpft da, noch immer umstritten zwischen den Ogern, dem Syndikat und den letzten Soldaten eines Königreichs, das sie zurückzuerobern versucht.",
		source = "https://warcraft.wiki.gg/wiki/Arathi_Highlands_(Classic)",
	},
	[1418] = {
		name = "Ödland",
		short = "Das Ödland ist eine rissige Wüste aus trockener Erde, verstreuten Felsbrocken und gewundenen Schluchten, auf allen Seiten von Bergen umschlossen. Kaum etwas überlebt hier außer Kojoten, Pumas und Bussarden.",
		full = "Das Ödland ist eine rissige Wüste aus trockener Erde, verstreuten Felsbrocken und gewundenen Schluchten, auf allen Seiten von Bergen umschlossen. Kaum etwas überlebt hier außer Kojoten, Pumas und Bussarden.\n\nIn den nördlichen Ausläufern liegen die Ruinen von Uldaman, ein Werk der uralten Irdenen. Als man sie freilegte, lieferten sie die ersten Hinweise auf die erhabene Herkunft der Zwerge, und Prospektoren aus Ironforge strömten herbei, um die Ruine nach Artefakten der Titanen zu durchsuchen. Doch die Steingrufttroggs, nach Jahrtausenden des Schlummers erwacht, metzelten die Forscher nieder und verteidigen ihre geraubte Stadt nun mit wilder Entschlossenheit. Eine große Festung der Dunkeleisenzwerge steht gleich südlich von Uldaman, und ihre Zwerge liegen im Krieg mit den Ogern vom Stamm der Dustbelcher und mit den Drachen, die im Osten zwischen der Brut der schwarzen Drachen nisten.\n\nSpäter wurde hier Kargath gegründet, der einzige Außenposten der Horde in Khaz Modan, errichtet, damit die Orcs ihre abtrünnigen Verwandten vom Blackrockklan im Auge behalten konnten. Kriegshäuptling Thrall selbst entsandte die Expeditionsstreitmacht von Kargath, um Rend Blackhand zur Strecke zu bringen.",
		source = "https://warcraft.wiki.gg/wiki/Badlands_(Classic)",
	},
	[1419] = {
		name = "Verwüstete Lande",
		short = "Die Verwüsteten Lande tragen ihren Namen zu Recht. Der rote Lehm unter den Füßen war einst braune Erde, Teil eines finsteren Sumpfes namens Schwarzes Fenn, bevor die Horde der Orcs hier das Dunkle Portal aufriss und nach Azeroth strömte.",
		full = "Die Verwüsteten Lande tragen ihren Namen zu Recht. Der rote Lehm unter den Füßen war einst braune Erde, Teil eines finsteren Sumpfes namens Schwarzes Fenn, bevor die Horde der Orcs hier das Dunkle Portal aufriss und nach Azeroth strömte. Die Magie, die an jenem Tag hindurchsickerte, versengte den Boden rot und tötete ihn für immer. Nichts wächst hier nun außer zähem Wüstengestrüpp und zähen Wüstengeschöpfen: Basilisken, Skorpione, Hyänen.\n\nErzmagier Khadgar und die Kirin Tor errichteten Burg Nethergarde, um die Ruine des Tores zu bewachen und dafür zu sorgen, dass nie wieder etwas hindurchkam. Zwei Jahre lang hielt der Frieden, bis die Horde von Draenor das Portal wieder öffnete und die Burg belagerte. Als Ner'zhuls Ritual Draenor zu zerreißen begann, nutzten Khadgar und die anderen Magier den Schädel des Gul'dan, um den steinernen Rahmen des Portals von der anderen Seite aus in Stücke zu sprengen, und kappten die Brücke zwischen den Welten für immer.\n\nHeute halten die Magier und Paladine von Nethergarde noch immer ihre grimmige Wacht über das tote Portal, eine verschworene, humorlose Gemeinschaft, die niemandem traut und kein Versäumnis verzeiht, der einzige Unterschlupf in einem Land, in dem die Stürme vom östlichen Meer über den verbackenen Boden abfließen, bevor sie etwas Gutes bewirken können.",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands_(Classic)",
	},
	[1420] = {
		name = "Tirisfal",
		short = "Der Himmel über Tirisfal hängt seit Jahren kränklich grün, und die Bäume klammern sich an das bisschen Leben, das die Seuche ihnen gelassen hat.",
		full = "Der Himmel über Tirisfal hängt seit Jahren kränklich grün, und die Bäume klammern sich an das bisschen Leben, das die Seuche ihnen gelassen hat. Einst waren dies friedliche Höfe unter König Terenas, wo Generationen still zwischen Mühlen und Kürbisfeldern lebten. Das endete, als Arthas Menethil Lordaeron verwüstete und die Seuche durch das Land fegte, sein Volk tötete und es als Sklaven des Lichkönigs wiedererweckte. Massengräber zeugen noch heute davon, wo die Toten zu zahlreich waren, um sie ordentlich zu bestatten. Nahe Balnirs Bauernhof war es, Monate später, dass Sylvanas Windrunner ihre Banshees gegen Arthas wandte und dem Todesritter einen vergifteten Pfeil verpasste, bevor Kel'Thuzads Skelette sie vertrieben.\n\nAus diesem Verderben gingen die Verlassenen hervor, Sylvanas' Untote mit freiem Willen, die das Land für sich beanspruchten. Ihre Feinde haben es nie verlassen: Der Scharlachrote Kreuzzug hält das alte Scharlachrote Kloster im Norden, Fanatiker, die alles verbrennen und jagen, was nicht menschlich ist.",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades_(Classic)",
	},
	[1421] = {
		name = "Silberwald",
		short = "Der Silberwald ist ein weiter, uralter Wald, der sich entlang der schroffen Westküste Lordaerons erstreckt. Das Land reicht von recht flach bis hügelig und liegt eingebettet zwischen noch höheren Bergen.",
		full = "Der Silberwald ist ein weiter, uralter Wald, der sich entlang der schroffen Westküste Lordaerons erstreckt. Das Land reicht von recht flach bis hügelig und liegt eingebettet zwischen noch höheren Bergen. Der Wald ist unheimlich still, abgesehen von gelegentlichem unnatürlichem Heulen, das zwischen den Bäumen widerhallt. Bemooste Überhänge erzittern in der kalten Brise, und die Bäume sind allesamt krank oder sterbend. Verfallene Gehöfte und verlassene Minen sind über das Land verstreut, heute Heimat der finstereren Bewohner der Wälder.\n\nDieses Waldland ist heimgesucht und wild, geprägt von hohen Kiefern mit silberner Rinde, die über grasbewachsene Hügel ragen. Einst schützte die Allianz den Silberwald, als er noch grün und lebendig war. Nun ist der Ort in geisterhafte Nebel gehüllt. Die Verlassenen beherrschen den nördlichen Wald und liefern sich ständig Gefechte mit den elenden Moderfellgnollen. Was von der menschlichen Bevölkerung übrig ist, hält den südlichen Wald, doch sie sind verzweifelt und ihre Kräfte dünn gesät. Dalaran entsendet häufig Expeditionen in den Silberwald, um diese Menschen zu verteidigen und die Seuche der Untoten und den Fluch der Worgen zu erforschen – ein rätselhaftes Leiden, das seine Opfer bei Mondaufgang in blutrünstige, wolfsgestaltige Worgen verwandelt.\n\nGilneas und das Vorgebirge von Hillsbrad grenzen im Süden an den Wald, während Tirisfal im Norden liegt. Der Lordameresee bildet die Ostgrenze des Silberwalds.\n\nObwohl das Gebiet den Verlassenen gehört, wird ihr Anspruch von den Zauberern Dalarans und von Agenten der Geißel bestritten, die einige der verwüsteten Felder und Gehöfte in Besitz genommen haben. Die Moderfellgnolle operieren von der rätselhaften Insel Fenris aus und greifen jeden erbittert an, der sich ihren Umtrieben zu nähern wagt. Im Südwesten liegt Pyrewood, dessen Bewohner unter den Fluch von Erzmagier Arugal gefallen sind und sich des Nachts in blutrünstige Worgen verwandeln. Arugal haust in den nahen, düsteren Türmen von Burg Shadowfang.\n\nIm Silberwald wird häufig gekämpft, denn Streitkräfte der Allianz aus Southshore ziehen in die verfluchten Wälder, um das Grabmal anzugreifen oder in Shadowfang einzudringen. Er ist der Rand der Heimat der Verlassenen und der südlichste Punkt, an dem die Folgen der Seuche an den Pflanzen zu sehen sind.",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "Westliche Pestländer",
		short = "Einst waren dies die schönsten Ackerlande im Norden Lordaerons, bewaldet und grün, die von Andorhal aus die Kornspeicher des Königreichs füllten und von der Halle in Hearthglen aus regiert wurden.",
		full = "Einst waren dies die schönsten Ackerlande im Norden Lordaerons, bewaldet und grün, die von Andorhal aus die Kornspeicher des Königreichs füllten und von der Halle in Hearthglen aus regiert wurden. Eben dieser Wohlstand wurde zur Waffe, mit der man sie zerstörte.\n\nNach dem Plan des Lichkönigs trug der Kult der Verdammten seine Seuchenenergien in tragbaren Kesseln nach Süden, versteckte sie in Dörfern treuer Kultisten und stellte die vier größten auf Andorhals eigenen Feldern auf. Das Korn selbst wurde vergiftet und ging auf Wagen, die niemand zu hinterfragen dachte, hinaus nach ganz Lordaeron. Die Menschen, die ihr eigenes Brot aßen, erkrankten, starben und erhoben sich wieder als Sklaven des Lichkönigs. Die Wälder erholten sich nie. Die Kiefern stehen grau mit braunen Nadeln unter einem Schleier kränklichen Nebels, ihre Stämme von Wucherungen geschwollen.\n\nWas an Ordnung übrig ist, wurde nach dem Zusammenbruch des Königreichs gerettet, als der Scharlachrote Kreuzzug Burg Mardenholde in Hearthglen einnahm und von dort aus gegen die Untoten vorstieß, die den Rest des Landes hielten. Inmitten von alledem bewahrt nur ein Ort seinen Frieden: Uthers Grabmal, geweiht Uther Lichtbringer, ein Boden, den die Seuche nie berührt hat.",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "Östliche Pestländer",
		short = "Der Boden hier war einst Ackerland, die Dörfer der Östlichen Lande rund um Stratholme verstreut, die zweite Stadt Lordaerons. Nichts davon ist geblieben.",
		full = "Der Boden hier war einst Ackerland, die Dörfer der Östlichen Lande rund um Stratholme verstreut, die zweite Stadt Lordaerons. Nichts davon ist geblieben. Die Erde ist nun braun und krank, die Bäume sind zu Pilzen aufgequollen, und die Luft ist dick von orangefarbenem Nebel.\n\nNach Stratholme kam Prinz Arthas auf der Suche nach dem Ursprung einer Seuche, die bereits die Stadtbewohner befallen hatte. Lord Uther, Meister der Silbernen Hand, weigerte sich, ihn die Stadt säubern zu lassen. Arthas enthob ihn des Kommandos, löste die Silberne Hand an Ort und Stelle auf und ließ die Bewohner Stratholmes selbst über die Klinge springen, statt sie als Diener der Geißel auferstehen zu lassen. Dabei blieb es nicht – er jagte den Schreckenslord Mal'Ganis in den Norden, kehrte als Todesritter zurück und tötete seinen eigenen Vater, um das Königreich Lordaeron zu beenden.\n\nAlexandros Mograine stellte aus den Resten der Silbernen Hand einen Kreuzzug auf, um die Ruinen zurückzuerobern, und nahm Tyrs Hand und halb Stratholme ein, bevor sein Tod seinen Orden in die Argentumdämmerung und den Scharlachroten Kreuzzug spaltete, der diese Felder noch immer hält, endlos gegen die Geißel kämpft und niemanden sonst willkommen heißt.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "Vorgebirge von Hillsbrad",
		short = "Der Boden von Hillsbrad ist fruchtbar und seine Hügel sind grün, und Reisende sagen, so habe ganz Lordaeron ausgesehen, bevor die Seuche kam.",
		full = "Der Boden von Hillsbrad ist fruchtbar und seine Hügel sind grün, und Reisende sagen, so habe ganz Lordaeron ausgesehen, bevor die Seuche kam. Darin liegt ebenso seine Grausamkeit wie sein Trost: Das Land erinnert an das, was überall sonst verloren ging, während die Menschen, die es halten, denselben Krieg führen, der den Rest verwüstet hat.\n\nZu Beginn des Zweiten Krieges überfielen orcische Plünderer seine Küstenstädte, und Orgrim Schicksalshammer selbst ritt gegen Burg Durnholde, um Zul'jin aus ihren Zellen zu befreien. Jahrzehnte später war es Thrall, der durch diese Hügel zog, die versprengten Orcklans sammelte und sich dann nachts nach Southshore schlich, um dessen Schiffe zu stehlen und die neue Horde über das Meer nach Kalimdor zu bringen.\n\nWas die Orcs begonnen haben, haben die Verlassenen fortgesetzt. Sie nahmen Tarrens Mühle als ihren südlichsten Besitz ein und machten es zum Aufmarschgebiet gegen die Menschen von Southshore und den Feldern von Hillsbrad, die treu zur Allianz standen.\n\nKiefernwälder sprenkeln nun das Ackerland, und noch immer führen Straßen über die Weiden zu den düsteren Siedlungen der Verlassenen im Norden, als warte das Land selbst noch darauf, welche Seite es behalten wird.",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "Hinterland",
		short = "Nach dem Krieg der Drei Hämmer verließen die Wildhammerzwerge ihre Tunnel in Grim Batol, zogen nach Norden und bauten ihre Heimstätten oberirdisch am Aerie Peak.",
		full = "Nach dem Krieg der Drei Hämmer verließen die Wildhammerzwerge ihre Tunnel in Grim Batol, zogen nach Norden und bauten ihre Heimstätten oberirdisch am Aerie Peak. Sie wandten sich von Stein und Esse ab, hin zu Himmel und Schwinge, und verbanden sich so eng mit den wilden Greifen der Gegend, dass sie in ihrer eigenen Stadt einen gewaltigen steinernen Greifen errichteten, um dieses Band zu ehren. Die Waldtrolle, die dieses Land bereits hielten, Überreste des einst großen Reichs der Amani, sahen in den Zwergen Eindringlinge auf dem Boden ihrer Ahnen und überfielen die Horste, wann immer sie konnten.\n\nAls die Horde im Zweiten Krieg durch das Land fegte, stürzten sich Than Kurdran Wildhammer und seine Reiter, die bis dahin nicht einmal von solchen Eindringlingen gewusst hatten, mit sturmgeladenen Hämmern aus dem Himmel auf die Kolonnen der Orcs und hetzten sie ohne Unterlass. Orgrim Schicksalshammer hoffte, die Kräfte der Allianz ins Hinterland zu locken, um Quel'Thalas ungehindert angreifen zu können, doch Anduin Lothar durchschaute den Plan und ritt selbst an Kurdrans Seite, und gemeinsam schlugen sie die Eindringlinge und trieben sie zurück ins Alteracgebirge. Dafür versprach Kurdran der Allianz die Hilfe seines Volkes.",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "Dun Morogh",
		short = "Tiefer Schnee liegt über Dun Morogh, auf allen Seiten von den Bergen Khaz Modans umschlossen, und seine Pässe werden stets von zwergischen Truppen bewacht.",
		full = "Tiefer Schnee liegt über Dun Morogh, auf allen Seiten von den Bergen Khaz Modans umschlossen, und seine Pässe werden stets von zwergischen Truppen bewacht. Bevor die Berge irgendjemand anderem gehörten, gehörten sie den Eistrollen der Frostmane, die sich in der Region niedergelassen hatten, nachdem sie sich in längst vergangenen Zeiten vom Reich der Drakkari abgespalten hatten.\n\nDas änderte sich, als die ersten Gnome aus Uldaman emporstiegen und ihren Verstand darauf richteten, der Kälte wie den Trollen zu trotzen, indem sie befestigte Behausungen tief in die Gipfel gruben. Fünfhundert Jahre später folgten ihnen die Zwerge aus Uldaman hinauf, angezogen von denselben Bergen, die sie am Horizont erblickt hatten, und errichteten Ironforge unter dem höchsten von ihnen. Als sie die Gnome bereits in der Nähe angesiedelt fanden, schlossen die beiden Völker eine Freundschaft, die nie zerbrochen ist: Die Zwerge liehen ihre Kraft, um Gnomeregan zu erbauen, und die Gnome teilten die Geheimnisse ihrer Maschinen. Gemeinsam zerschlugen ihre Heere die Frostmanetrolle, trieben die Überlebenden zurück in die Hügel und beendeten die Herrschaft der Trolle über das Land für immer.\n\nGnomeregan ist nun verloren, eine Ruine, und sein Volk drängt sich in Ironforge zusammen, um dort Zuflucht zu finden.",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "Sengende Schlucht",
		short = "Einst war dies grünes Land, ein Teil des Rotkammgebirges, bis der Boden selbst vor mehr als zweihundertdreißig Jahren aufgerissen wurde.",
		full = "Einst war dies grünes Land, ein Teil des Rotkammgebirges, bis der Boden selbst vor mehr als zweihundertdreißig Jahren aufgerissen wurde.\n\nIm Krieg der Drei Hämmer suchte Zaubererthan Thaurissan von den Dunkeleisenzwergen nach einer Waffe, um seine Feinde zu vernichten. Er und sieben seiner treuesten Zwerge griffen unter die Welt und riefen Mächte an, die besser geschlafen hätten. Was antwortete, war kein Diener, sondern ein Meister: der uralte Feuerlord Ragnaros. Sein Erwachen riss den Blackrock aus der Erde empor, schwärzte das Land meilenweit und begrub die Hauptstadt der Dunkeleisenzwerge, Thaurissan, als Schutt unter sich. Die versengten Steppen im Süden wurden als die Brennende Steppe bekannt; dieses verwüstete Tal im Norden wurde zur Sengenden Schlucht.\n\nNicht alle Dunkeleisenzwerge blieben ihrem Klan nach dem Untergang treu. Eine Anzahl von ihnen spaltete sich ab, nannte sich Thoriumbruderschaft und errichtete die Thoriumspitze mit Blick auf die gewaltige Grube, die ihre einstigen Verwandten in den Talboden getrieben hatten, um das Treiben der Dunkeleisenzwerge von oben zu beobachten.",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "Brennende Steppe",
		short = "Der Himmel über der Brennenden Steppe verliert nie seinen roten Schimmer, erhellt von vereinzelten Ausbrüchen des Blackrock, und der Boden kühlt niemals ab.",
		full = "Der Himmel über der Brennenden Steppe verliert nie seinen roten Schimmer, erhellt von vereinzelten Ausbrüchen des Blackrock, und der Boden kühlt niemals ab. Zweihundert Jahre bevor sich das Dunkle Portal öffnete, kamen Dunkeleisenzwerge als Verbannte aus Ironforge hierher. Ihr Zaubererthan Thaurissan suchte elementare Diener herbeizurufen, um den Krieg der Drei Hämmer gegen die Klans der Bronzebeard und Wildhammer zu gewinnen. Was antwortete, war kein Diener, sondern Ragnaros der Feuerlord, einst von den Titanen verbannt. Seine Ankunft ließ die Berge um ihn herum schmelzen, türmte im Herzen der Explosion einen Vulkan auf und vernichtete die Zwerge, die ihn gerufen hatten. Was nördlich dieses neuen Gipfels lag, wurde zur Sengenden Schlucht; was südlich lag, zur Brennenden Steppe, seither voller Narben.\n\nOrcs ließen sich während des Ersten Krieges an den Hängen des Vulkans nieder und hielten die Blackrockspitze im Zweiten Krieg als Festung. Die Blackrockorcs kehrten danach zurück und sind noch immer dort, getreu den alten brutalen Sitten aus der Zeit vor Thralls Waffenstillstand. Schwarze Drachen unter Nefarian halten die oberen Ebenen der Spitze, und es heißt, Ragnaros brüte noch immer irgendwo unter alldem.",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "Wald von Elwynn",
		short = "Als die Orcs im Ersten Krieg kamen, marschierten Tausende durch Elwynn, um Stormwind einzukesseln und es von allem außer dem Meer abzuschneiden.",
		full = "Als die Orcs im Ersten Krieg kamen, marschierten Tausende durch Elwynn, um Stormwind einzukesseln und es von allem außer dem Meer abzuschneiden. Ritterchampion Anduin Lothar führte die Ritter von Stormwind in einem Sturmangriff mitten durch den Wald, traf die orcische Nachhut überraschend und zersprengte sie. Das verschaffte der Stadt Zeit, doch nicht genug. Kriegshäuptling Blackhand nahm bald Goldhain und Moonbrook ein, die letzten Orte zwischen der Horde und dem König, und die Burg von Stormwind wurde geplündert. Lothar führte die Überlebenden zum Meer und fort nach Lordaeron, und die Ruinen der Stadt gehörten eine Zeit lang dem Sturmrächerklan. Verstreute orcische Katapulte liegen noch immer zerbrochen und verrottend überall in der Gegend, die letzten Zeugnisse jener Besatzung.\n\nDie Weinberge von Nordhain, östlich der Stadt, waren einst der Stolz der Bauern von Stormwind. Als die Steinmetzgilde für die Jahre, die sie mit dem Wiederaufbau der zerstörten Hauptstadt verbracht hatte, keinen Lohn erhielt und die Adligen sie auflösten, statt die Schuld zu begleichen, entlud sich der Zorn von Gildenmeister Edwin VanCleef in Aufständen, bei denen Königin Tiffin Ellerian Wrynn getötet wurde und aus denen die Defiasbruderschaft hervorging. Die Bruderschaft vertrieb die Bauern aus Nordhain und besetzte ihre Felder.",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "Gebirgspass der Totenwinde",
		short = "Der Gebirgspass der Totenwinde schneidet sich durch die Berge im Herzen von Azeroth und verbindet den Dämmerwald mit den Sümpfen des Elends. Vor zwanzig Jahren zählte er noch zum Rotkammgebirge.",
		full = "Der Gebirgspass der Totenwinde schneidet sich durch die Berge im Herzen von Azeroth und verbindet den Dämmerwald mit den Sümpfen des Elends. Vor zwanzig Jahren zählte er noch zum Rotkammgebirge.\n\nDer Elfenbeinturm von Karazhan, einst der Sitz der Macht des dunklen Zauberers Medivh, steht im Zentrum dieser zerklüfteten Gegend und lässt böse Magie in das Land sickern. Die Bäume sind versteinert und blattlos, und ein schrecklicher Wind heult durch die Schlucht. Oger, Dämonen, Untote und ein paar menschliche Zigeuner streifen durch das Innere – und man flüstert, eine neue Macht habe den Elfenbeinturm in Besitz genommen, und die Oger und Dämonen stünden unter ihrem Bann.",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "Dämmerwald",
		short = "Ein Mantel unnatürlicher Nacht liegt über dem Dämmerwald, und er hat sich nie gehoben.",
		full = "Ein Mantel unnatürlicher Nacht liegt über dem Dämmerwald, und er hat sich nie gehoben. Was einst ein schöner Teil des Waldes von Elwynn war, ist nun ein verfluchtes, sterbendes Land: Die Bäume wuchsen unter dem schwarzen Nebel knorrig, die Toten erhoben sich aus ihren Gräbern, und Worgen schlichen mit der Dunkelheit selbst herein, angelockt vom Wirken der Sense von Elune. Oger, die vom Gebirgspass der Totenwinde hereindrängen, haben das Elend nur noch vertieft.\n\nDer Schutz Stormwinds bedeutet hier längst nichts mehr, und die Menschen, die geblieben sind, haben gelernt, ohne ihn standzuhalten. Ihre Miliz, die Nachtwache, patrouilliert auf den Straßen und bewacht Dunkelhain vor allem, was sich in den Schatten regt – Skelettkrieger und Ghule, wilde Worgen und obendrein Männer der Defias.\n\nIm Herzen des Waldes liegt der Krater eines längst erloschenen Vulkans, gehüllt in ein Zwielicht, das sanfter ist als die Dunkelheit ringsum. Darin steht einer der Großen Bäume, dessen Wurzeln zum Smaragdgrünen Traum hinabreichen, und der Einfluss der schlafenden Druiden prägt alles, was in der Nähe wächst. Dahinter erstrecken sich verlassene Gehöfte und die weitläufigen Gräber des Friedhofs von Rabenflucht, die sich Jahr um Jahr füllen, seit die Dunkelheit hereinbrach.",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "Loch Modan",
		short = "Die Wasser von Loch Modan ruhen eingebettet in grauem Stein, gehalten vom Stonewroughtdamm, einem Meisterwerk zwergischer Baukunst, dem kein anderes Bauwerk auf Azeroth je gleichgekommen ist.",
		full = "Die Wasser von Loch Modan ruhen eingebettet in grauem Stein, gehalten vom Stonewroughtdamm, einem Meisterwerk zwergischer Baukunst, dem kein anderes Bauwerk auf Azeroth je gleichgekommen ist. Die Berge ragen auf allen Seiten steil empor, licht bewaldet mit Kiefern und Birken, und der See selbst liegt still und ruhig da, als hätte ihn nie etwas gestört.\n\nDer See war einst ein Schlachtfeld. Im Zweiten Krieg fielen die Orcs der Horde in die Region ein und stellten sich hier der Allianz. Ironforge hielt stand. Seine Zwerge warfen die Orcs zurück und eroberten Loch Modan zurück, und die Trümmer jenes Krieges wurden nie ganz beseitigt: Zerbrochene Katapulte und zerschmetterte Balliste liegen noch immer halb versunken verstreut auf dem Seegrund und seinen Inseln, der einzige verbliebene Beweis, dass dieses ruhige Wasser einst ein Ort des Tötens war.",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "Rotkammgebirge",
		short = "Das Rotkammgebirge liegt östlich des Waldes von Elwynn, nordöstlich des Dämmerwalds und südlich der Brennenden Steppe.",
		full = "Das Rotkammgebirge liegt östlich des Waldes von Elwynn, nordöstlich des Dämmerwalds und südlich der Brennenden Steppe.\n\nAls idyllische Region voller rauschender Flüsse, hoch aufragender Ulmen und ansteigender Höhen steht das Rotkammgebirge unter dem Schutz Stormwinds, obwohl es seit dem Zweiten Krieg formell unabhängig ist. Es bleibt eine der letzten friedlichen Regionen von Azeroth, seine Bewohner ruhig und zufrieden, und es versorgt Stormwind mit Holz, Fisch und Feldfrüchten. Doch der Frieden ist nicht vollkommen: Eine Streitmacht von Blackrockorcs aus der Brennenden Steppe hält Burg Steinwacht, auch wenn sie bislang für sich bleiben. Verglichen mit dem Verfall von Westfall hält das Rotkammgebirge noch zusammen.\n\nAm Nordufer des Immerruhsees liegt die Stadt Seenhain, belagert von Gnollen und Blackrockorcs aus den umliegenden Hügeln. Südlich davon verbindet die Wegkreuzung, die als Drei Ecken bekannt ist, Seenhain mit Elwynn und dem Dämmerwald und über den Uferpfad mit Burg Steinwacht, eine Straße, auf der sich Drachenwelpen, Gnolle, Murlocs und wilde Tiere tummeln.\n\nDie Oberfläche des Sees wirkt ruhig genug, doch unter ihr lauern Murlocs, und hartnäckig hält sich das Gerücht von einem Seeungeheuer in seinen Tiefen.",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "Schlingendorntal",
		short = "Das Schlingendorntal ist ein weiter Dschungel südlich des Dämmerwalds. Dschungeltrolle patrouillieren durch diesen dampfenden Regenwald, und Naga jagen entlang seiner Küsten, während Schlingdornranken und wilde Tiere das Reisen gefährlich machen.",
		full = "Das Schlingendorntal ist ein weiter Dschungel südlich des Dämmerwalds. Dschungeltrolle patrouillieren durch diesen dampfenden Regenwald, und Naga jagen entlang seiner Küsten, während Schlingdornranken und wilde Tiere das Reisen gefährlich machen.\n\nDas Tal war einst das Herz des Reichs der Gurubashi, dessen große Städte überall in der Region standen. Nach dem Fall des Reiches zerfielen diese Städte zu Ruinen, doch noch immer hausen Trolle darin. Zul'Gurub im Nordosten war einst die Hauptstadt der Gurubashi.\n\nBooty Bay war ursprünglich eine kleine, von Menschen besiedelte Hafenstadt, bis sie von Trollen überrannt wurde. Die Goblins des Steamwheedle-Kartells vertrieben später die Trolle aus der Bucht, nahmen sie für sich in Besitz und bauten sie zu ihrem Hauptsitz in den Östlichen Königreichen aus.\n\nIm Norden liegt ein Truppenlager, das die Expedition von Oberst Kurzen errichtet hat. Dort wurde der Geist des Obersts von einem Ogermagier namens Mai'Zoth ergriffen, der ein Artefakt namens Gedankenauge nutzte, um Kurzens Willen zu beugen und seine Männer zu befehligen. Einige von Kurzens Soldaten lehnten sich gegen ihren besessenen Befehlshaber auf, flohen nach Westen und gründeten ihm zum Trotz ein Rebellenlager.",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "Sümpfe des Elends",
		short = "Unter dem schwarzen Wasser des Sumpfes liegt ein Tempel, älter als das Leid, das diesem Ort seinen Namen gab.",
		full = "Unter dem schwarzen Wasser des Sumpfes liegt ein Tempel, älter als das Leid, das diesem Ort seinen Namen gab. Als das Reich der Gurubashi fiel, floh eine abtrünnige Gruppe von Trollen namens Atal'ai in die Marschen und errichtete den Tempel von Atal'Hakkar, wo sie grausige Riten vollzogen, um ihren dunklen Loa, Hakkar den Seelenschinder, in die Welt zurückzurufen. Ihre Magie verzerrte die Pflanzen und Tiere rund um den Tempel, bis die Verderbnis nicht länger unbemerkt bleiben konnte. Ysera, die Herrin der Träume, erfuhr von den Plänen des Kults und wandte ihre Macht gegen sie, indem sie den Tempel im größten Moor versenkte, bevor Hakkar zurückkehren konnte. Doch sie traute den Trollen nicht zu, ihren Gott für immer aufzugeben. Sie setzte ihren Gefährten Eranikus und eine Schar grüner Drachen ein, um ewige Wacht über die Ruine zu halten, damit sie nie wieder dazu dienen konnte, solches Übel auf die Welt loszulassen. Grüne Drachkin patrouillieren noch immer auf ihren Befehl durch diese Sümpfe, und der versunkene Tempel bleibt unter dem Wasser versiegelt, bewacht statt zerstört.",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "Westfall",
		short = "Der Wind streicht nun ungehindert über die Felder von Westfall, denn nichts Hohes ist mehr übrig, das ihn brechen könnte. Einst war dies die Kornkammer Stormwinds, die das junge Königreich über Generationen ernährte.",
		full = "Der Wind streicht nun ungehindert über die Felder von Westfall, denn nichts Hohes ist mehr übrig, das ihn brechen könnte. Einst war dies die Kornkammer Stormwinds, die das junge Königreich über Generationen ernährte.\n\nAls die Steinmetzgilde für den Wiederaufbau Stormwinds nach dem Zweiten Krieg keinen Lohn erhielt und sich die Wache gegen ihre Proteste wandte, führte Gildenmeister Edwin VanCleef seine Männer ins Versteck auf dem Land, statt sich König Varians Gerechtigkeit zu stellen. Dort wurden sie zur Defiasbruderschaft, und unter einer Scheune in Moonbrook fand VanCleef ein altes Stollennetz, tief genug, um den Bau einer Waffe zu verbergen, die Stormwind vom Meer aus in Brand setzen sollte. Er vertrieb die Bauern, heuerte Flusspfotengnolle an, um das Land zu halten, und ließ seine Männer die Felder niederbrennen und die Erde mit Salz bestreuen, damit dort nie wieder etwas wachsen würde.\n\nStormwind, dessen Kassen erschöpft waren, überließ Westfall sich selbst. Nur Gryan Stoutmantle antwortete und stellte auf der Späherkuppe die Volksmiliz auf, als keine Armee kam.\n\nDie Felder, die VanCleef versalzen hat, haben Westfall das nicht verziehen. Das Gras wächst noch immer gelb und dünn, wo einst der Weizen schulterhoch stand.",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "Sumpfland",
		short = "Ein kalter, grauer Sumpf liegt unterhalb des Damms, Nebel über seinen Flüssen und Tümpeln, auf drei Seiten von Bergen umschlossen und im Westen zum Meer hin offen.",
		full = "Ein kalter, grauer Sumpf liegt unterhalb des Damms, Nebel über seinen Flüssen und Tümpeln, auf drei Seiten von Bergen umschlossen und im Westen zum Meer hin offen. Überall liegen Trümmer verstreut, die Überreste zwergischer Festungen, die einst dieses Land hielten. Nun halten es stattdessen Murlocs, wilde Tiere und abtrünnige Orcs, und der Hafen von Menethil ist der einzige wirkliche Stützpunkt der Allianz hier.\n\nDieser Hafen war nicht immer Boden der Allianz. Als der Zweite Krieg begann, baute Orgrim Schicksalshammer seine Invasionsflotte auf einer kleinen Insel in der Baradinbucht, damit seine Schiffe Lordaerons Küsten angreifen konnten, ohne sich dessen Landverteidigung stellen zu müssen. Das Sumpfland zahlte dafür: Orcs und Drachen zehrten schwer vom Land, und das Wild wurde knapp. Nach dem Krieg wurde der Hafen wiederaufgebaut und zu Ehren von Terenas Menethil II. in Hafen von Menethil umbenannt.\n\nDanach kam der Fall von Grim Batol. Der rote Drachenschwarm, der dort zum Dienst am Dragonmawklan versklavt worden war, wandte sich nach seiner Befreiung gegen seine Peiniger, und der Klan wurde zerschlagen, seine Überlebenden in die Wildnis zerstreut. Alexstrasza sah es als Bürde ihres Schwarms an, den Berg versiegelt zu halten, und seither halten rote Drachkin Wacht über ihn.",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "Teldrassil",
		short = "Als Malfurion Sturmgrimm im Smaragdgrünen Traum verschwand, übernahm Erzdruide Fandral Staghelm an seiner Stelle die Führung des Zirkels des Cenarius und überzeugte den Zirkel der Urtume, dass die Zeit gekommen sei, einen neuen Weltenbaum wachsen zu lassen und die Unsterblichkeit zurückzugewinnen, die die Nachtelfen verloren hatten.",
		full = "Als Malfurion Sturmgrimm im Smaragdgrünen Traum verschwand, übernahm Erzdruide Fandral Staghelm an seiner Stelle die Führung des Zirkels des Cenarius und überzeugte den Zirkel der Urtume, dass die Zeit gekommen sei, einen neuen Weltenbaum wachsen zu lassen und die Unsterblichkeit zurückzugewinnen, die die Nachtelfen verloren hatten. Im Verhüllten Meer ließen sie Teldrassil wachsen, die Krone der Erde, und bauten Darnassus in seinen Ästen. Doch Nozdormu, der den ersten Weltenbaum gesegnet hatte, verweigerte diesem seinen Segen und nannte den Wunsch anmaßend, und die Unsterblichkeit, nach der die Nachtelfen strebten, kehrte nie zurück.\n\nMit der Zeit geriet das Land auf Teldrassil unter eine unheilvolle Präsenz. Furbolgs und Grells in seinen Wäldern verfielen dem Wahnsinn, Satyrn tauchten zwischen den Bäumen auf, und die großen Schildkröten und Drescher, die einst die Gewässer um den Baum durchschwammen, flohen, um an den Ufern der Dunkelküste zu stranden und zu sterben. Der Ursprung dieser Verderbnis bleibt ein Rätsel, und Malfurion ist nicht aus dem Traum zurückgekehrt, um ihn zu ergründen.",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "Dunkelküste",
		short = "Ein grauer Nebel liegt meist über dieser Küste, und die Nachtelfen deuten ihn seit Langem als Warnung.",
		full = "Ein grauer Nebel liegt meist über dieser Küste, und die Nachtelfen deuten ihn seit Langem als Warnung. Regen und Fels machen das Land unwirtlich, und jeder Versuch, es über den Handelsposten Auberdine hinaus zu besiedeln, ist gescheitert.\n\nVor zehntausend Jahren standen hier die Zwillingsstädte Ameth'Aran und Bashal'Aran, beherrscht von Athrikus Narassin. Als der Krieg der Ahnen die Welt zerbrach und die Große Teilung hereinbrach, schwor Athrikus seinem Volk, er werde es retten. Er hielt sein Versprechen dem Wortlaut nach und brach es dem Sinn nach: Er band ihre Seelen in Seelensteine und erzählte ihnen, dies sei ewiges Leben, während er sie in Wahrheit aussaugte, um seine eigene Macht zu nähren. Die Städte verfielen zu Ruinen, und was heute zwischen den Steinen umgeht, hat keine völlige Ruhe gefunden.\n\nNach dem Dritten Krieg brachte Fandral Staghelm Druiden des Zirkels des Cenarius an die Dunkelküste und pflanzte an diesem Ufer einen neuen Weltenbaum, Teldrassil.",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "Eschental",
		short = "Eschental ist uralter Wald, dicht an alten Bäumen und alter Magie, und um ihn wurde seit jeher gekämpft.",
		full = "Eschental ist uralter Wald, dicht an alten Bäumen und alter Magie, und um ihn wurde seit jeher gekämpft.\n\nDie Orcs des Warsongklans kamen zuerst als Holzfäller hierher. Goblins unter Neeloc Greedyfingers schlugen die Bäume kahl, bis die ansässigen Furbolgs sie zurückdrängten, und Grommash Höllschrei zerschlug seinerseits die Furbolgs und die Schildwachen, um sich die Hilfe der Goblins zu sichern. Cenarius kam selbst, um wiederherzustellen, was gefällt worden war, und es kostete ihn das Leben: Die Herren der Brennenden Legion verwandelten sein Vertrauen in eine Falle, und Grommash streckte ihn nieder.\n\nSchlimmeres folgte, als die Legion mit voller Macht auf Eschental marschierte. Archimondes Höllenbestien fielen brennend vom Himmel, und Untote und Dämonen strömten von Osten herein und überwältigten die zerstrittenen Heere von Nachtelfen, Orcs und Menschen gleichermaßen, bevor sie weiter auf den Berg Hyjal vorrückten. Tyrande Whisperwind weckte Malfurion aus dem Smaragdgrünen Traum, und er fand den Wald, an den er sich erinnerte, verzehrt von Teufelsfeuer und erstickender Fäulnis.\n\nDieser alte Streit fand nie ein Ende. Die Nachtelfen halten noch immer Astranaar und ihre verstreuten Zufluchten; die Horde hat ihre Lager der Warsong tief in den Süden und Osten getrieben, fällt Holz und drängt die Schildwachen zurück. Keine der beiden Seiten hat den Kampf um diese Wälder je zu Ende gebracht.",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "Tausend Nadeln",
		short = "Die Schlucht verläuft tief und trocken, ihr Grund verliert sich zwischen hoch aufragenden Tafelbergen, bis sie sich im Osten zur Schimmernden Ebene öffnet, einer großen Salzpfanne unter weitem Himmel.",
		full = "Die Schlucht verläuft tief und trocken, ihr Grund verliert sich zwischen hoch aufragenden Tafelbergen, bis sie sich im Osten zur Schimmernden Ebene öffnet, einer großen Salzpfanne unter weitem Himmel. Der Sonnenaufgang vom Freiwindposten oder von den Höhen um den Düsterwolkengipfel ist über solch kargem Land ein spektakulärer Anblick. Der Druide Quentin hat sich gefragt, ob die harte Dürre hier, so dicht neben dem üppigen Dschungel des benachbarten Feralas, überhaupt natürlich ist, oder ob sie das Mal einer seltsamen Magie ist, die auf das Land gewirkt wurde.\n\nDie hohen Tafelberge gehören den Tauren, und der Freiwindposten ist ihre Feste zwischen ihnen. Unangefochten haben sie diesen Boden nicht gehalten. Die ansässigen Zentauren bedrängten sie, und schlimmer noch, ihre eigenen Verwandten vom Stamm der Grimmtotem wandten sich gegen sie, sodass die Tauren vom Freiwindposten gezwungen waren, Stamm gegen Stamm um das Hochland zu kämpfen. Nur mit der Hilfe der Horde schlugen sie die Zentauren und die Grimmtotem zurück.",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "Steinkrallengebirge",
		short = "Der Steinkrallengipfel hat stets den Geistern gehört, bevor er irgendeinem Volk gehörte.",
		full = "Der Steinkrallengipfel hat stets den Geistern gehört, bevor er irgendeinem Volk gehörte. Die Nachtelfen unterhalten auf seinem Gipfel eine Grabstätte und eine Lichtung, wo sie mit der Natur Zwiesprache halten, und auch den Tauren ist er heilig, denn hier beobachtete einst das unsterbliche Orakel die Fäden des Schicksals, wie die Erdenmutter sie wob. Die Legende sagt, die ersten Tauren, die sich in diesen Bergen niederließen, trugen flammende Totems hinauf zu den höchsten Klippen und entzündeten Feuer für An'she, um die Dunkelheit zu vertreiben, die am Stein haftete.\n\nWeiter unten am Berg segnete Elune vor langer Zeit einen Brunnen mit der Gabe der Heilung. Später nahmen Harpyien die nahen Gipfel ein, fingen die Windreiter, die dort nisteten, und verunreinigten das Wasser des Brunnens. Thrall zog gegen sie, mit Cairne Bloodhoof und seinen Tauren an seiner Seite, und zerschlug eine Zentaurenbande, um eine Glyphe der Läuterung zu erringen und zu reinigen, was die Harpyien verdorben hatten. Die befreiten Windreiter trugen sie hinauf zum Gipfel selbst.\n\nDieser alte Frieden mit dem Land ist im Süden dahin. Die Venture Co. hat die Scherwindklippe kahl geschlagen, ihre Bäume gefällt, die Luft mit Ruß erstickt und das Wasser mit Öl und Abfall verseucht, bis die Geister des Berges so laut aufschrien, dass Schamanen bis nach Orgrimmar es hören konnten.",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "Desolace",
		short = "Theradras, Tochter von Therazane der Steinmutter, schlummerte einst unter einem fruchtbaren Grasland.",
		full = "Theradras, Tochter von Therazane der Steinmutter, schlummerte einst unter einem fruchtbaren Grasland. Tauren-Schamanen, die glaubten, die Erdenmutter selbst wohne dort unten, riefen jahrzehntelang nach ihr, bis endlich etwas antwortete – nicht die Erdenmutter, sondern Theradras, wütend aus ihrem Schlaf gerissen. Sie zehrte vom Land, um ihre geschwächte Gestalt wiederherzustellen, und die Wiesen starben in einem einzigen Augenblick. Die Tauren nannten, was übrig blieb, Desolace.\n\nZaetar, Sohn des Waldfürsten Cenarius, kam, um sie zu bannen, doch stattdessen liebte er sie, und sie erwiderte seine Liebe. Aus ihrer Verbindung gingen die Zentauren hervor, und ihre erste Tat war es, ihren eigenen Vater zu ermorden. Sie vermehrten sich rasch und vertrieben die Tauren aus dem Land, womit Jahrhunderte des Krieges zwischen den beiden Völkern begannen.\n\nTheradras haust noch immer in Maraudon unter den westlichen Schluchten, und dorthin führen die Zentauren den Ursprung ihres Volkes zurück.",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "Feralas",
		short = "Feralas erhebt sich fremdartig zwischen seinen Nachbarn, ein Regenwald uralter Bäume, wo die Öden ringsum nur Staub verheißen.",
		full = "Feralas erhebt sich fremdartig zwischen seinen Nachbarn, ein Regenwald uralter Bäume, wo die Öden ringsum nur Staub verheißen. Überall in seinem Grün stehen die Ruinen der Elfen, halb verschlungen von Wurzeln und Ranken, die größte unter ihnen die verschüttete Stadt Düsterbruch.\n\nDie Gordunni-Oger beherrschen Feralas heute, und sie haben es sich zu eigen gemacht, indem sie es zerstören. Ganze Waldstriche haben sie niedergerissen, und ihr Makel hat sich wie eine Krankheit über das Land gelegt. Jenseits der Mauern von Düsterbruch brennen ihre Raubtrupps Dörfer nieder und ermorden Reisende in den südlichen Wäldern, eine Verderbnis, die sich durch die Wildnis ausbreitet und auf die Ruinen darunter zurückgeht.\n\nTauren der Grimmtotem leben noch immer verstreut in der Region, gejagt von jenen, die nicht vergessen haben, was der Stamm getan hat.",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "Marschen von Dustwallow",
		short = "Die Mücken hören hier nie auf, und der Schlamm ebenso wenig.",
		full = "Die Mücken hören hier nie auf, und der Schlamm ebenso wenig. Die Bäume verflechten ihre Wedel so dicht über dem Wasser, dass das Sonnenlicht nur gebrochen herabfällt, und Krokilisken und Murlocs lauern im Brackwasser, wo das Meer auf den Sumpf trifft. Im Süden sammeln sich schwarze Drachen in solcher Zahl, dass man den Ort schlicht den Drachensumpf nennt.\n\nJaina Prachtmeer schuf in dieser Wildnis die erste wahre Heimat, als sie ihr Volk nach der Schlacht am Berg Hyjal hierherführte, um Theramore auf seiner felsigen Insel zu gründen. Die Mauern ihrer Stadt glänzen, doch sie schließen sie auch ein: Jenseits der verstreuten Kontrollposten an der Straße zum Brachland bleibt der Sumpf so wild wie eh und je, und ihre Garnison ist durch stille Fahnenfluchten ausgedünnt, die niemand erklären kann.\n\nHier war es auch, dass der Frieden zwischen Horde und Allianz endgültig zerbrach. Admiral Daelin Prachtmeer führte die Flotte von Kul Tiras im Sumpf gegen die Horde, und das Gefecht, das folgte, endete mit seinem Tod und besiegelte den Übergang vom Waffenstillstand zur offenen Feindschaft.\n\nBrackenwall steht dort, wo die Oger der Stonemaul der Horde ihre Tore öffneten. Dahinter liegt die Straße zum Brachland leer und verfällt, bewacht von nichts als den Raptoren und Spinnen, denen dieser Boden schon immer gehört hat.",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "Tanaris",
		short = "Sand füllt den Ort, an dem einst ein Dschungel stand. Bevor die Welt zerbrach, war Tanaris grün und wurde vom Reich der Gurubashi als Gebiet beansprucht.",
		full = "Sand füllt den Ort, an dem einst ein Dschungel stand. Bevor die Welt zerbrach, war Tanaris grün und wurde vom Reich der Gurubashi als Gebiet beansprucht. Als die Große Teilung das Land zerriss, starb der Dschungel, und was übrig blieb, verbuk zu Dünen und Stein. Ein Trollstamm fand sich hier gestrandet, als das Wasser zurückwich, und im Laufe der langen Jahre, die folgten, beugten sich ihre Körper und ihre Sitten der Wüste, bis sie nicht länger die Trolle waren, die sie gewesen waren, sondern Sandtrolle, die Sandwüter, ein Volk, geformt von dem Land, das sie gefangen hielt.\n\nDie Goblins des Steamwheedle-Kartells wählten diese Einöde für ihren Handel und gründeten Gadgetzan und den Hafen von Steamwheedle, denn die Wüste ist ihrer versunkenen Heimat so nah, wie Kalimdor es ihnen zu siedeln erlaubt. Die Docks von Steamwheedle reichen hinaus zu den Inseln dahinter, doch die Goblins behalten ihre Schiffe für sich und weigern sich, irgendein anderes Volk über das Wasser zu bringen.\n\nUnter den Dünen und den südlichen Bergen erstrecken sich die Tunnel meilenweit, größtenteils unkartiert, und wer hinabsteigt, kehrt nicht immer zurück, um zu berichten, was er gefunden hat.",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "Azshara",
		short = "Seit zehntausend Jahren hält der Herbst Azshara umfangen, seine Bäume glühen orange und rot über Klippen, die in Korallen abfallen, wo noch immer eine Stadt liegt.",
		full = "Seit zehntausend Jahren hält der Herbst Azshara umfangen, seine Bäume glühen orange und rot über Klippen, die in Korallen abfallen, wo noch immer eine Stadt liegt. Azshara war einst die größte Metropole, die die Nachtelfen je erbaut hatten, und als der Krieg der Ahnen kam, versank der größte Teil davon im Meer. Ein paar zerbrochene Gebäude klammern sich noch an den Klippenhang und blicken hinab auf ihre eigenen Ruinen unter dem Wasser.\n\nLange danach, als Illidan Sturmgrimm mit seinen Naga vom Berg Hyjal nach Norden floh, Mur'gul und Satyrn im Gefolge, verwüstete er Azsharas Küste und zerstörte die Häfen der Nachtelfen, damit ihm niemand zum Grabmal des Sargeras folgen konnte. Maiev Shadowsong und ihre Wächterinnen kamen hinter ihm her und machten die wahnsinnigen Kreaturen nieder, die er hinter sich zurückließ.",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "Teufelswald",
		short = "Die Bäume im Teufelswald wachsen nicht so sehr, als dass sie eitern. Ihre Rinde sondert ein kränkliches Sekret ab, ihre Blätter hängen schwarz und gekräuselt herab, und die Tiere unter ihnen kommen verkrüppelt und hungrig aus der Verderbnis im Boden hervor.",
		full = "Die Bäume im Teufelswald wachsen nicht so sehr, als dass sie eitern. Ihre Rinde sondert ein kränkliches Sekret ab, ihre Blätter hängen schwarz und gekräuselt herab, und die Tiere unter ihnen kommen verkrüppelt und hungrig aus der Verderbnis im Boden hervor.\n\nDie Fäulnis war kein Zufall der Natur. Als die Brennende Legion gegen den Berg Hyjal vorrückte, befahl Archimonde, den Wald zu zerstören, um die Nachtelfen zu schwächen, die den Berg bewachten, und der Schreckenslord Tichondrius führte diesen Befehl mit einem Hexenmeisterrelikt von schrecklicher Macht aus, dem Schädel des Gul'dan. Das Land antwortete, indem es von innen heraus starb: Urtume wurden faulig und gewalttätig, Tiere mutierten, die Erde selbst wurde vergiftet.\n\nHier traf Illidan Sturmgrimm die Entscheidung, die den Rest seines Lebens prägte. Als man ihm sagte, der Schädel könne gegen eben die Verderbnis gewendet werden, die er verursacht hatte, ging Illidan allein in den Teufelswald, streckte Tichondrius nieder und nahm das Relikt an sich. Er gab es danach nicht mehr her. Sein Hunger nach Magie erwies sich als stärker als seine Vorsicht, und weil er die Macht der Legion selbst nutzte, wurde er von seinem eigenen Bruder Malfurion verstoßen.",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "Un'Goro-Krater",
		short = "Der Un'Goro-Krater liegt abgeschottet zwischen drei Wüsten, eine grüne Wunde, eingesunken im Süden Kalimdors, wo die Welt vergisst, karg zu sein.",
		full = "Der Un'Goro-Krater liegt abgeschottet zwischen drei Wüsten, eine grüne Wunde, eingesunken im Süden Kalimdors, wo die Welt vergisst, karg zu sein. Dinosaurier, älter als jede Erinnerung, ziehen durch seinen Dschungel, manche zu Größen herangewachsen, die kein Lebewesen erreichen sollte, und Elementare aus Erde und Feuer wandeln unbehelligt zwischen ihnen. Auf den Graten darüber stehen Pylonen, die noch niemand je erklärt hat.\n\nWährend des Krieges der Sandstürme wurden die Nachtelfen durch diesen Krater bis an den Rand der Wüste von Tanaris zurückgedrängt, und dort brach der Vormarsch der Qiraji. Etwas in Un'Goro selbst ließ die Eindringlinge das Land nicht einnehmen, doch niemand hat gesagt, was es war.\n\nEine Expedition unter der Führung von Williden und Hol'anyee Marshal versuchte einst, hier Fuß zu fassen, doch die Wildheit des Kraters erwies sich als mehr, als sie erwartet hatten. Ihre Lager wurden überrannt, und die Überlebenden flohen auf höheres Gelände, wo sie sich an dem Ort verschanzten, der heute Marshals Zuflucht heißt.",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "Moonglade",
		short = "Moonglade liegt eingebettet in einem Ring aus Bergen, ein verborgenes Tal, in dem der Wald nie Verderbnis gekannt hat.",
		full = "Moonglade liegt eingebettet in einem Ring aus Bergen, ein verborgenes Tal, in dem der Wald nie Verderbnis gekannt hat. In seinem Herzen ruht der Elune'ara See, benannt nach der Göttin selbst, und in der Stadt Nighthaven an seinem Ufer wandeln Tauren und Nachtelfen ohne Streit miteinander, verbunden durch eine gemeinsame Ehrfurcht vor der Natur, die die Wächter von Moonglade nicht gebrochen sehen wollen.\n\nIn dieses Tal kam Malfurion Sturmgrimm in den Tagen des Krieges der Ahnen, als die Nachtelfen am Rande des Untergangs gegen die Legion standen. Malfurion wusste, dass sein Volk allein nicht siegen konnte, und er führte Tyrande Whisperwind und seinen Bruder Illidan in die heilige Stille von Moonglade, um Cenarius um Hilfe anzuflehen. Der Halbgott antwortete, und nachdem die Große Teilung die Welt neu geformt hatte, zogen die Bewahrer des Hains und die Dryaden, die hier Zuflucht gefunden hatten, in sie hinaus. Cenarius selbst ging nie fort, und Moonglade wurde zum heiligsten Ort druidischer Verehrung.\n\nUnter seinen unzähligen Hügeln schlafen die Heiligtümer vergangener Druiden, und unter den Wassern des Elune'ara schläft der Halbgott Omen, einst geliebt von Elune, in unruhigem Schlummer.",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "Silithus",
		short = "Die Wüste liegt am äußersten südwestlichen Rand Kalimdors, eine Öde aus zerbrochenem Fels und Sand, die man über den breiten Pfad aus Un'Goro erreicht.",
		full = "Die Wüste liegt am äußersten südwestlichen Rand Kalimdors, eine Öde aus zerbrochenem Fels und Sand, die man über den breiten Pfad aus Un'Goro erreicht. Unter ihrer Oberfläche liegt der Überrest des Reichs der Aqir, Ahn'Qiraj, dessen zentralen Tempel die Nachtelfen versiegelten, um etwas Schreckliches am Erwachen zu hindern. Die über Silithus verstreuten Ruinen und die Stöcke der Silithiden, die nun den Sand durchlöchern, sind Beweis genug, dass die Versiegelung nicht gehalten hat.\n\nVor langer Zeit wurden die Qiraji selbst hinter den Skarabäuswall getrieben und dort nach dem Krieg der Sandstürme eingekerkert. Ihre Diener, die Silithiden, blieben frei, und im Laufe der Jahrhunderte vermehrten sie sich und breiteten sich über ganz Südkalimdor aus, bis die Nachtelfen die Bedrohung für zu groß hielten, um länger nur zuzusehen, und sich stattdessen daranmachten, die Tore von Ahn'Qiraj wieder zu öffnen, um zu vollenden, was der Wall nur aufgeschoben hatte.\n\nDer Zirkel des Cenarius hält von Burg Cenarius aus Wacht, verfolgt die Schwärme der Silithiden und wägt ab, ob sie eine Gefahr sind, zu groß, als dass ein einzelnes Volk ihr allein begegnen könnte.",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "Winterspring",
		short = "Der Schnee liegt unberührt über Winterspring, seine Schönheit ungestört, selbst dort, wo Dämonen die südlichen Gebiete überrannt haben. Einst war es die Heimat vieler Angehöriger des blauen Drachenschwarms, unter ihnen Haleh, die Gefährtin von Malygos.",
		full = "Der Schnee liegt unberührt über Winterspring, seine Schönheit ungestört, selbst dort, wo Dämonen die südlichen Gebiete überrannt haben. Einst war es die Heimat vieler Angehöriger des blauen Drachenschwarms, unter ihnen Haleh, die Gefährtin von Malygos.\n\nVor zehntausend Jahren errichteten die Hochgeborenen hier die Stadt Kel'Theril, nachdem sie den Kristall von Zin-Malor aus einem Tempel in Eldarath gestohlen hatten. Sie konnten nicht widerstehen, seine Macht zu erproben, und als er zersprang, verschlang sie der Fluch, den er entfesselte. Die Große Teilung vollendete, was der Kristall begonnen hatte, und Kel'Theril verfiel zu Ruinen. Seine Toten gingen nie fort. Später kamen Hochelfen aus Quel'Thalas, um die Splitter des Kristalls zu suchen, und derselbe Wahnsinn ergriff sie. Nun wandeln ihre Geister durch die Ruinen neben denen, die sie erforschen wollten.\n\nGoblins halten Everlook im Herzen des Tals, und die Nachtelfen halten hier noch immer ihre eigene Wacht und hüten eine Heimat, die älter ist als sie beide.",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "Stormwind",
		short = "Stormwind erhob sich in weißem Stein, nachdem die Horde der Orcs es niedergebrannt hatte, wiedererrichtet von der Steinmetzgilde unter dem jungen König Varian.",
		full = "Stormwind erhob sich in weißem Stein, nachdem die Horde der Orcs es niedergebrannt hatte, wiedererrichtet von der Steinmetzgilde unter dem jungen König Varian. Doch als die Kassen der Krone durch Kriegsschulden erschöpft waren und der Adel der Gilde ihren Lohn verweigerte, wurde der Protest von Gildenmeister Edwin VanCleef mit der Auflösung der Gilde beantwortet. Es folgten Aufstände, und im Chaos wurde Königin Tiffin Wrynn getötet. Varians Zorn trieb die Steinmetze ins Exil nach Westfall, wo sie zur Defiasbruderschaft wurden – während hinter dem Thron eine Beraterin namens Katrana Prestor im Stillen den König für ihre eigenen Zwecke gegen die Gilde aufbrachte.\n\nKönig Varian ist seither unter verdächtigen Umständen verschwunden, und auf Drängen von Lady Prestor wurde die Krone seinem jungen Sohn, Prinz Anduin, übergeben, um die Ordnung im Reich zu wahren. Hochlord Bolvar Fordragon dient als Regent von Stormwind und Befehlshaber seiner Streitkräfte, während Lady Prestor ihn beim Einsatz der Mittel des Königreichs berät, unverdächtigt und unangefochten in der Burg.",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "Orgrimmar",
		short = "Orgrimmar erhob sich in den Jahren nach der Schlacht am Berg Hyjal, als Kriegshäuptling Thrall sein Volk an eine öde Küste Kalimdors führte.",
		full = "Orgrimmar erhob sich in den Jahren nach der Schlacht am Berg Hyjal, als Kriegshäuptling Thrall sein Volk an eine öde Küste Kalimdors führte. Er nannte das Land nach seinem Vater Durotar, und die Stadt, die er dort errichtete, nannte er Orgrimmar, nach Orgrim Schicksalshammer, dem Freund und Mentor, der ihn geformt hatte. Sie wurde schnell, aber nicht nachlässig erbaut: dicke Mauern, gewaltige Tore, hohe Türme, und die Berge in ihrem Rücken wurden ausgehöhlt, um Teil der Festung selbst zu werden, sodass das Land über die Stadt wachte.\n\nDie Horde, die sie erbaute, war nicht die Horde, die einst brennend über die Welt hinweggefegt war. Nachdem der dämonische Fluch gebrochen war, wandte sich Thralls Volk von der Eroberung dem Überleben zu, und Orgrimmar wurde ebenso sehr von anderen wie von Orcs erbaut – Goblins, Tauren und Darkspeartrolle arbeiteten an ihrer Seite, und der Mok'Nathal Rexxar legte bei dem Werk mit Hand an. Zentauren, Harpyien, Donnerechsen, Kobolde und Stacheleber stellten die junge Stadt in ihren ersten Jahren auf die Probe, doch sie hielt stand und wurde nicht nur den Orcs zur Heimat, sondern auch Trollen, Tauren und schließlich den Verlassenen, die neu in der Horde willkommen geheißen wurden.\n\nSelbst der Wind ist hier kein Freund: Die Klingenwinde fegen mit solcher Wucht durch die Täler, dass sie die Dächer von Gebäuden reißen, die ohne Sorgfalt errichtet wurden.",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "Ironforge",
		short = "Ironforge ist die Hauptstadt der Zwerge, gehauen in die Tiefen des Berges Ironforge im Norden von Dun Morogh, der Stammheimat der Zwerge und einer der ältesten Städte auf Azeroth.",
		full = "Ironforge ist die Hauptstadt der Zwerge, gehauen in die Tiefen des Berges Ironforge im Norden von Dun Morogh, der Stammheimat der Zwerge und einer der ältesten Städte auf Azeroth. Sie ist die Hauptstadt von Khaz Modan, regiert von König Magni Bronzebeard vom Bronzebeardklan.\n\nAls weitläufige unterirdische Stadt der Handwerker, Forscher, Bergleute und Krieger, berühmt für ihren Gewerbefleiß und als Handelszentrum der Allianz, ist Ironforge zu gleichen Teilen Festung und Hauptstadt, ein Zeugnis der Stärke und Widerstandskraft der Zwerge. Die Stadt besteht aus konzentrischen Ringen, kleineren Ebenen tiefer unter der Erde, die alle von der namensgebenden Großen Schmiede in ihrer Mitte ausstrahlen. Sie ist voller schmaler Gänge, in die Felswände gebauter Läden und höhlenartiger Räume. Die Stimmung ist geschäftig, laut und industriell und doch gemütlich; Feuer prasseln in den Herden der Gasthäuser und Läden, und viel zwergisches Gelächter und Ausgelassenheit ist zu hören. Anders als Stormwind und Darnassus ist die Stadt eine gewaltige Höhle, die von den Zwergen selbst in die Erde gehauen wurde; Decke und Boden bestehen beide aus hartem Stein.",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "Thunder Bluff",
		short = "Thunder Bluff erhebt sich auf vier windgepeitschten Tafelbergen über dem Grasland von Mulgore, erreichbar nur über Aufzüge aus Seil und Holz, von Tauren gefertigt, oder über lange Brücken, die zwischen den Anhöhen gespannt sind.",
		full = "Thunder Bluff erhebt sich auf vier windgepeitschten Tafelbergen über dem Grasland von Mulgore, erreichbar nur über Aufzüge aus Seil und Holz, von Tauren gefertigt, oder über lange Brücken, die zwischen den Anhöhen gespannt sind. Zelte, Langhäuser und bemalte Totems krönen jeden Gipfel. Über Generationen zogen die Tauren als Nomadenvolk umher, rastlos gehetzt von den Zentauren, die durch Kalimdor streiften. Es war Cairne Bloodhoof, Häuptling des Stammes der Bloodhoof, der dieses Exil beendete. Als Kriegshäuptling Thrall und seine Neue Horde während des Dritten Krieges nach Mulgore kamen, vereinte sich ihre Stärke mit der Cairnes, und gemeinsam zerschlugen sie die Zentauren und gewannen das Grasland endlich für die Tauren. Auf den Tafelbergen errichtete Cairne eine Zuflucht für jeden versprengten Stamm, und mit der Zeit beugten sich diese Stämme seiner Herrschaft als ein einziges Volk, zuweilen uneins über den weiteren Weg, doch nie über seine Weisheit, sie zu führen.\n\nDie Klippen tragen noch immer das Gewicht jener Gründung in ihren Anhöhen und Brücken, in den Zelten der Stämme, die sich unter dem Dach eines einzigen Häuptlings versammelt haben.",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "Darnassus",
		short = "Die Nachtelfen erbauten Darnassus nach dem Dritten Krieg, als ihre lange Unsterblichkeit sie verlassen hatte. Viele konnten die plötzliche Last von Alter und Gebrechlichkeit nicht ertragen.",
		full = "Die Nachtelfen erbauten Darnassus nach dem Dritten Krieg, als ihre lange Unsterblichkeit sie verlassen hatte. Viele konnten die plötzliche Last von Alter und Gebrechlichkeit nicht ertragen. Eine Anzahl trauernder Druiden beschloss, einen neuen Weltenbaum zu pflanzen, um ihr Band mit der ewigen Welt wiederherzustellen. Da Malfurion Sturmgrimm verschollen war, übernahm Fandral Staghelm den Mantel des Erzdruiden und führte das Unterfangen an. Der Baum, den sie wachsen ließen, Teldrassil, erhob sich vor der Küste, bis seine Krone die Wolken durchbrach, und in seinen Ästen gründeten die Nachtelfen ihre Stadt als Zeugnis für das Überleben ihres Volkes.\n\nDarnassus liegt offen zum Himmel, anders als die engen, ummauerten Städte der Menschen und Zwerge. Es ist um einen weiten See herum erbaut, dessen Ufer von anmutigen Brücken verbunden werden, und seine Wege sind mit gefallenem Laub bedeckt. Der Tempel des Mondes erhebt sich über die Bäume als Sitz der Hohepriesterin Tyrande Whisperwind und ihrer Schwestern der Elune, neben der säulengeschmückten Halle der Gerechtigkeit, in der die Schildwachen ihre Wacht halten. Die Stadt ist geblieben, wozu sie erbaut wurde: eine friedvolle Zuflucht und ein Denkmal für ein Volk, das lernt, mit der Sterblichkeit zu leben.",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "Undercity",
		short = "Lange bevor die Verlassenen sie sich zu eigen machten, hatte Undercity einen Namen und einen Zweck. Tief unter dem Palast von Lordaeron verliefen die uralten Grüfte seiner königlichen Toten, seine Kerker, seine Kanäle.",
		full = "Lange bevor die Verlassenen sie sich zu eigen machten, hatte Undercity einen Namen und einen Zweck. Tief unter dem Palast von Lordaeron verliefen die uralten Grüfte seiner königlichen Toten, seine Kerker, seine Kanäle. Sie waren nur für Gefangene und Leichen gedacht, doch die Ärmsten von Lordaerons Volk drängten sich dennoch hinab in die Dunkelheit, und die Razzien der Wachen, die sie vertreiben sollten, hatten nie lange Bestand.\n\nAls der Griff des Lichkönigs um seine Schöpfungen nachließ, brach Sylvanas Windrunner mit jenen Untoten, die ihren Verstand bewahrt hatten, von der Geißel los und wandte sich gegen Arthas, den gefallenen Prinzen, der sie zu dem gemacht hatte, was sie war. Sie lockte ihn im zerstörten Königreich in eine Falle; er entkam mit Kel'Thuzads Hilfe und floh nach Norden, um selbst zum Lichkönig zu werden. Sylvanas und ihre Anhänger, als Herren des Feldes zurückgeblieben, nannten sich die Verlassenen und beanspruchten die Grüfte unter der zerstörten Hauptstadt, wo sie die Festung vollendeten, die die Geißel begonnen hatte.\n\nWas heute dort steht, ist ein zur Verteidigung erbautes Labyrinth: Ströme giftigen Schlamms fließen durch jede Straße, und die Luft ist so dick von Dämpfen, dass die Lebenden kaum atmen können. Für die Verlassenen ist es ein Zufluchtsort in einer Welt, die sie noch immer jagt.",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
}

